varying vec4 vColor;
uniform float soft;
void main() {
  vec2 p = gl_PointCoord - 0.5;
  float d = max(abs(p.x), abs(p.y));
  if (d > 0.5) discard;
  float a = vColor.a;
  if (soft > 0.5) a *= smoothstep(0.5, 0.15, length(p));
  gl_FragColor = vec4(vColor.rgb, a);
}

